"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

/**
 * The one script behind every built visual (the hero phone and the visuals in
 * src/components/visuals). Each visual's story is CSS @keyframes in its module
 * (generated by scripts/motion.mjs from scripts/motion-spec.mjs), so the
 * browser moves it on its own clock: no JavaScript tick, no gate to pass.
 * Only transform and opacity change.
 *
 * - The animations are in the server-rendered page, paused (globals.css:
 *   [data-demo] without data-run). This lets them run on mount.
 * - An IntersectionObserver pauses a visual only while it is fully off screen
 *   and lets it run otherwise. It reads the callback's last entry: WebKit can
 *   batch several entries for one element, and the last is the current one.
 * - The pause button holds it (data-hold); a second press lets it run.
 * - `loop` (the hero) plays round; anything else plays once and holds its
 *   last frame.
 * - With reduced motion the same stories run on the same timings as opacity
 *   crossfades, with nothing moving (the generated keyframes' second set).
 *   Everything here works the same in both.
 * - It fills in the visitor's times ([data-clock]) once, on mount, and the
 *   ticket timers ([data-timer]) from the visual's clock (a vis-clock
 *   animation on the wrapper, globals.css).
 * - ?debug=motion shows a panel with each visual's state.
 */

const time = (d: Date) => d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
const day = (d: Date) => d.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });

function fill(el: HTMLElement) {
  const now = Date.now();
  el.querySelectorAll<HTMLElement>("[data-clock]").forEach((n) => {
    const kind = n.dataset.clock!;
    // Minutes to add: "ready" is the storefront's now + 20; others say so in data-add.
    const add = Number(n.dataset.add ?? (kind === "ready" ? 20 : 0));
    const d = new Date(now + add * 60000);
    n.textContent =
      kind === "status" ? time(d).replace(/\s?[AP]M$/, "") : kind === "day" ? day(d) : kind === "date" ? d.toLocaleDateString("en-US") : kind === "placed" ? d.toLocaleString("en-US") : time(d);
  });
}

/** The wrapper's own clock: where the story is, in ms from the top (of the loop, for the hero). */
function clockOf(el: HTMLElement) {
  return el.getAnimations?.().find((a) => (a as CSSAnimation).animationName === "vis-clock");
}

function position(el: HTMLElement, steps: readonly number[], loop?: number) {
  const clock = clockOf(el);
  const t = Number(clock?.currentTime ?? 0);
  return loop ? t % loop : Math.min(t, steps[steps.length - 1]);
}

const stepAt = (steps: readonly number[], t: number) => steps.reduce((n, at, i) => (t >= at ? i : n), 0);

/* ---------- ?debug=motion ---------- */

type Entry = { name: string; el: HTMLElement; steps: readonly number[]; loop?: number; seen: boolean | null; entries: number };
const registry = new Set<Entry>();
let panel: HTMLElement | null = null;

function state(e: Entry) {
  const el = e.el;
  const now = el.hasAttribute("data-hold")
    ? "paused: button"
    : el.hasAttribute("data-done")
      ? "done"
      : !el.hasAttribute("data-run")
        ? "paused: off screen"
        : "running";
  return matchMedia("(prefers-reduced-motion: reduce)").matches ? `${now} (reduced motion)` : now;
}

function draw() {
  if (!panel) return;
  const rows = [...registry].map((e) => {
    const anims = e.el.getAnimations?.({ subtree: true }) ?? [];
    const running = anims.filter((a) => a.playState === "running").length;
    const t = position(e.el, e.steps, e.loop);
    return [
      e.name,
      state(e),
      e.seen === null ? "none yet" : `${e.seen} (${e.entries})`,
      `${stepAt(e.steps, t)}/${e.steps.length - 1}`,
      `${Math.round(t)}`,
      `${running}/${anims.length}`,
    ];
  });
  const head = ["visual", "play state", "isIntersecting (last entry; entries seen)", "step", "clock ms", "running animations"];
  const cell = (s: string, tag: string) => `<${tag} style="padding:2px 4px;text-align:left;vertical-align:top">${s}</${tag}>`;
  panel.innerHTML = `<table style="border-collapse:collapse"><tr>${head.map((h) => cell(h, "th")).join("")}</tr>${rows
    .map((r) => `<tr>${r.map((c) => cell(c, "td")).join("")}</tr>`)
    .join("")}</table><div style="padding:4px">${navigator.userAgent}</div>`;
}

function debug(entry: Entry) {
  if (new URLSearchParams(location.search).get("debug") !== "motion") return () => {};
  registry.add(entry);
  if (!panel) {
    panel = document.createElement("div");
    panel.setAttribute("data-motion-debug", "");
    panel.setAttribute(
      "style",
      "position:fixed;left:8px;right:8px;bottom:8px;z-index:9999;max-height:50vh;overflow:auto;background:#13213C;color:#fff;font:11px/1.35 ui-monospace,monospace;border-radius:8px;padding:4px",
    );
    document.body.append(panel);
    setInterval(draw, 250);
  }
  draw();
  return () => registry.delete(entry);
}

export function VisualPlayer({
  name,
  steps,
  loop,
  className,
  stageClassName,
  buttonClassName,
  description,
  pauseLabel,
  playLabel,
  children,
}: {
  /** The visual's name, for tests and evidence (data-visual). */
  name: string;
  /** When each step starts, in ms from the top. Step 0 is the first paint. Must match scripts/motion-spec.mjs. */
  steps: readonly number[];
  /** The hero's loop length in ms. Without it the visual plays once. */
  loop?: number;
  className: string;
  stageClassName: string;
  buttonClassName: string;
  description: string;
  pauseLabel: string;
  playLabel: string;
  children: ReactNode;
}) {
  const root = useRef<HTMLDivElement>(null);
  const [paused, setPaused] = useState(false);
  const end = steps[steps.length - 1];
  // Anything that moves for more than five seconds gets a pause button.
  const pausable = loop !== undefined || end > 5000;

  useEffect(() => {
    const el = root.current!;
    fill(el);
    const entry: Entry = { name, el, steps, loop, seen: null, entries: 0 };
    const undebug = debug(entry);

    // Start now; the observer pauses it only while it is fully off screen.
    el.dataset.run = "";
    const io = new IntersectionObserver(
      (entries) => {
        const last = entries[entries.length - 1];
        entry.seen = last.isIntersecting;
        entry.entries += entries.length;
        if (last.isIntersecting) el.dataset.run = "";
        else delete el.dataset.run;
      },
      { threshold: 0 },
    );
    io.observe(el);

    // Played once: the clock's end hides the pause button.
    const onEnd = (e: AnimationEvent) => {
      if (e.target === el && e.animationName === "vis-clock") el.dataset.done = "";
    };
    el.addEventListener("animationend", onEnd);

    // Ticket timers count up from the story's own clock (text only).
    const timers = [...el.querySelectorAll<HTMLElement>("[data-timer]")];
    const count = () => {
      const t = position(el, steps, loop);
      for (const timer of timers) {
        const secs = Number(timer.dataset.timer) + Math.max(0, Math.floor((t - Number(timer.dataset.from)) / 1000));
        const text = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, "0")}`;
        if (timer.textContent !== text) timer.textContent = text;
      }
    };
    const id = timers.length ? setInterval(count, 250) : undefined;

    return () => {
      io.disconnect();
      el.removeEventListener("animationend", onEnd);
      clearInterval(id);
      undebug();
    };
  }, [name, steps, loop]);

  return (
    <div
      ref={root}
      className={className}
      data-demo
      data-visual={name}
      data-steps={steps.join(" ")}
      data-loop={loop ? "" : undefined}
      data-hold={paused ? "" : undefined}
      data-pausable={pausable ? "" : undefined}
      style={{ "--vis-dur": `${loop ?? end}ms` } as CSSProperties}
    >
      <p className="sr-only">{description}</p>
      <div aria-hidden="true" className={stageClassName}>
        {children}
      </div>
      {pausable ? (
        <button type="button" className={buttonClassName} aria-label={paused ? playLabel : pauseLabel} onClick={() => setPaused(!paused)}>
          <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
            {paused ? <path d="M8 5v14l11-7L8 5Z" /> : <path d="M7 5h3.5v14H7V5Zm6.5 0H17v14h-3.5V5Z" />}
          </svg>
        </button>
      ) : null}
    </div>
  );
}
